#ifdef GL_ES
precision mediump float;
#endif
#define NC %%n_val%%
#define TAU 6.28
uniform vec2 u_resolution;
uniform float u_cir[NC * 5];
uniform vec3 u_cirC[NC];
uniform float u_t;
float sdfRec(vec2 p, vec4 r) {
	p = abs(p - r.xy);
	vec2 d = p - r.zw / 2.0;
	float outside = length(max(d, 0.0));
	float inside = min(max(d.x, d.y), 0.0);
	return outside + inside;
}
vec3 hsv2rgb(vec3 c) {
	c = vec3(c.x / 360.0, c.y / 100.0, c.z / 100.0);
	vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
	vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
	return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
vec3 adjustColors(vec3 c) {
	float l = length(c);
	float cof = 1.1;
	float ct = .23;
	float stp = .07;
	c *= abs(l - ct) < stp ? cof + (1. - cof * cof) * abs(l - ct) / (cof * stp) : 1. / cof;
	return c;
}
void main() {
	vec2 st = gl_FragCoord.xy / u_resolution.xy;
	float d[NC];
	for (int i = 0; i < NC; i++) {
		d[i] = sdfRec(gl_FragCoord.xy, vec4(u_cir[4 * i], u_cir[4 * i + 1], u_cir[4 * i + 2], u_cir[4 * i + 3]));
		d[i] = d[i] / (u_resolution.x) * 1.2;
		d[i] = pow(abs(d[i]), .03);

	}
	vec3 color = vec3(0.05);
	for (int i = 0; i < NC; i++) {
		color += (1.0 - d[i]) * hsv2rgb(u_cirC[i]);
	}

	color = adjustColors(color);
	//sometimes works, sometimes doesn't
	//depend on resolution, try both ways please
	//comment out/in

	gl_FragColor = vec4((color * 6.), 1.0);
}

